<script setup lang="ts">
/**
 * A key number with its label and direction of change (`design/components/stat.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/stat.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed } from 'vue'

import { Icon, type IconRole } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/stat.module.css'
import Badge from './Badge.vue'
import Sparkline from '../charts/Sparkline.vue'

export type DeltaDirection = 'up' | 'down'

export interface StatDelta {
  value: string
  direction: DeltaDirection
  positive?: boolean
}

export interface StatTrend {
  direction: DeltaDirection
  label: string
}

export interface StatFooter {
  primary: string
  secondary: string
}

export interface StatProps {
  delta?: StatDelta
  /**
   * Shown when there is no delta, such as "vs last week".
   */
  description?: string
  /**
   * The two-line footer: the interpretation, then the period it covers.
   */
  footer?: StatFooter
  icon?: IconRole
  label: string
  /**
   * Tabular figures, so a column of these lines up.
   */
  numeric?: boolean
  /**
   * The trend as a shape: a `Sparkline` at the value row's inline end. It can sit beside `trend`
   * (words for the direction, a shape for the path) and replaces neither `delta` nor `footer`.
   * `Sparkline` draws it, and renders nothing for fewer than two points.
   */
  spark?: readonly number[]
  /**
   * The sparkline's accessible name, as a function of the stat's label because the wording
   * belongs to the catalog; the default is `{label}, recent trend`.
   */
  sparkLabel?: (label: string) => string
  /**
   * The neutral movement chip, top-right. See `StatTrend` for why it is not `delta`.
   */
  trend?: StatTrend
  /**
   * Already formatted by the app.
   */
  value: string
}

defineOptions({ name: 'Stat', inheritAttrs: false })

const props = withDefaults(defineProps<StatProps>(), {
  numeric: true,
  sparkLabel: (label: string) => `${label}, recent trend`,
})
const positive = computed(() =>
  props.delta === undefined ? undefined : (props.delta.positive ?? props.delta.direction === 'up'),
)
</script>

<template>
  <div :class="styles.stat" data-member="stat">
    <!-- labelRow -->
    <div :class="styles.labelRow">
      <!-- label -->
      <span :class="styles.label">
        {{ label }}
      </span>
      <!-- labelEnd -->
      <span v-if="icon !== undefined || trend !== undefined" :class="styles.labelEnd">
        <!-- glyph -->
        <span v-if="icon !== undefined" :class="styles.glyph">
          <Icon :name="icon" />
        </span>
        <Badge v-if="trend !== undefined" variant="outline" :icon="trend.direction">
          {{ trend.label }}
        </Badge>
      </span>
    </div>
    <!-- valueRow -->
    <div :class="styles.valueRow">
      <!-- value -->
      <span :class="styles.value" :data-numeric="numeric ? '' : undefined">
        {{ value }}
      </span>
      <!-- spark -->
      <span v-if="spark !== undefined" :class="styles.spark">
        <Sparkline :data="spark" :label="sparkLabel(label)" />
      </span>
    </div>
    <!-- delta -->
    <span
      v-if="delta !== undefined"
      :class="styles.delta"
      :data-direction="delta.direction"
      :data-positive="positive ? '' : undefined"
    >
      <Icon :name="delta.direction" size="sm" />
      <span aria-hidden="true">
        {{ delta.value }}
      </span>
      <!-- spoken -->
      <span :class="styles.spoken">
        {{ `${delta.direction} ${delta.value} — ${positive ? 'positive' : 'negative'}` }}
      </span>
    </span>
    <!-- description -->
    <span v-else-if="description !== undefined" :class="styles.description">
      {{ description }}
    </span>
    <!-- footer -->
    <div v-if="footer !== undefined" :class="styles.footer">
      <!-- footerPrimary -->
      <span :class="styles.footerPrimary">
        {{ footer.primary }}
        <!-- footerGlyph -->
        <span v-if="trend !== undefined" :class="styles.footerGlyph">
          <Icon :name="trend.direction" size="sm" />
        </span>
      </span>
      <!-- footerSecondary -->
      <span :class="styles.footerSecondary">
        {{ footer.secondary }}
      </span>
    </div>
  </div>
</template>
